"""Finite end perimeter when the median gap is too narrow for grass.

The short line joining the original inner endpoints is retained explicitly.
The existing step/regular cap patterns mesh this perimeter. The default proves
positive separation over the complete affine end region. The optional finite
mode admits exact contact on the actual common inner-edge interval and checks
the ordered finite end cuts. Overlap and containment remain other branches.
"""
from . import bundle_cap_outline_nodes as outline


def construct(g, first, clipped, minimum_band, *, finite_contact=False):
    from .bundle_cap_input_nodes import _pick
    index=g.node('GeometryNodeInputIndex','Filled narrow cap perimeter identity').outputs[0]
    starts=[g.component(p,'X') for p in first]
    cut=g.component(clipped[0],'X')
    low=starts[0]
    for x in starts[1:]:low=g.math('MINIMUM',low,x)
    if finite_contact:
        # Only this interval belongs to BOTH finite inner edges. Earlier
        # positions lie beyond one original endpoint and cannot establish
        # physical overlap. The explicit end connector covers the stagger.
        low=g.math('MAXIMUM',starts[1],starts[2])
    sign=g.switch(g.compare(g.component(first[3],'Y'),g.component(first[0],'Y'),'GREATER_THAN'),-1.,1.)
    checks=[]
    for station in (low,cut):
        ys=[]
        for a,b,x in zip(first,clipped,starts):
            advance=g.math('SUBTRACT',g.component(b,'X'),x)
            fraction=g.math('DIVIDE',g.math('SUBTRACT',station,x),advance)
            ys.append(g.math('ADD',g.component(a,'Y'),g.math('MULTIPLY',fraction,
                g.math('SUBTRACT',g.component(b,'Y'),g.component(a,'Y')))))
            checks.append(g.compare(advance,outline.JOIN_ALLOWANCE,'GREATER_THAN'))
        gap=g.math('MULTIPLY',sign,g.math('SUBTRACT',ys[2],ys[1]))
        checks.extend((g.compare(gap,0. if finite_contact else outline.JOIN_ALLOWANCE,
                                 'GREATER_EQUAL' if finite_contact else 'GREATER_THAN'),
                       g.compare(gap,g.math('SUBTRACT',minimum_band,1e-5),'LESS_THAN')))
        for i,j in ((0,1),(2,3)):
            checks.append(g.compare(g.math('MULTIPLY',sign,g.math('SUBTRACT',ys[j],ys[i])),
                                    outline.JOIN_ALLOWANCE,'GREATER_THAN'))
    if finite_contact:
        # Together with convex finite member caps and nonnegative separation
        # on their common inner interval, this orders the finite end chain.
        # Contained/overlapping members still belong to the union constructor.
        for i in range(3):
            distance=g.math('MULTIPLY',sign,g.math('SUBTRACT',
                g.component(first[i+1],'Y'),g.component(first[i],'Y')))
            checks.append(g.compare(distance,0.,'GREATER_EQUAL'))
        for i in (0,2):
            quad=[first[i],clipped[i],clipped[i+1],first[i+1]]
            for k in range(4):
                left=g.vector('SUBTRACT',quad[(k+1)%4],quad[k])
                right=g.vector('SUBTRACT',quad[(k+2)%4],quad[(k+1)%4])
                turn=g.math('MULTIPLY',sign,g.component(g.vector('CROSS_PRODUCT',left,right),'Z'))
                checks.append(g.compare(turn,outline.EPS,'GREATER_THAN'))
    corners=[first[0],clipped[0],clipped[3],first[3],first[2],first[1]]
    # Walking from the owner to the partner defines winding in the local frame.
    ccw=g.compare(sign,0.,'GREATER_THAN')
    corners=[g.switch(ccw,b,a,'VECTOR') for a,b in zip(corners,reversed(corners))]
    line=g.node('GeometryNodeMeshLine','Six finite narrow-infill boundary segments')
    line.inputs['Count'].default_value=6
    a=_pick(g,index,corners)
    following=g.math('MODULO',g.math('ADD',index,1.),6.)
    b=_pick(g,following,corners)
    records=g.store(line.outputs['Mesh'],'st_cap_a',a,'FLOAT_VECTOR')
    records=g.store(records,'st_cap_b',b,'FLOAT_VECTOR')
    records=g.store(records,'st_cap_next',following,'INT')
    records=g.store(records,'st_cap_join_error',0.)
    if finite_contact:
        from . import bundle_axis_nodes as axis
        # Exact contact can repeat the same inner endpoint. Remove only the
        # zero/micrometre derived interval, retaining the original cyclic
        # order. The existing metric join allowance bounds any collapse.
        records=axis._select(g,records,g.compare(g.vector('DISTANCE',a,b),outline.MIN_SEGMENT,'GREATER_THAN'),
                             'Finite cap segments including exact inner-end contact')
        count=axis._size(g,records)
        following=g.math('MODULO',g.math('ADD',index,1.),count)
        end=g.sample(records,g.named('st_cap_a','FLOAT_VECTOR'),following,'FLOAT_VECTOR')
        error=g.vector('DISTANCE',g.named('st_cap_b','FLOAT_VECTOR'),end)
        checks.extend((g.compare(count,4,'GREATER_EQUAL','INT'),
            g.compare(g.stat(records,error,output='Max'),outline.JOIN_ALLOWANCE,'LESS_EQUAL')))
        records=g.store(records,'st_cap_next',following,'INT')
        records=g.store(records,'st_cap_join_error',error)
        records=g.store(records,'st_cap_b',end,'FLOAT_VECTOR')
    else:
        checks.append(g.stat(records,g.compare(g.vector('DISTANCE',a,b),outline.MIN_SEGMENT,'GREATER_THAN')))
    valid=g.all(*checks)
    cloud=g.node('GeometryNodeMeshToPoints','Finite narrow-infill boundary records');cloud.mode='VERTICES'
    g.set(records,cloud.inputs['Mesh'])
    return g.switch(valid,None,cloud.outputs['Points'],'GEOMETRY'),valid
